import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { TranslateService, TranslateModule } from '@ngx-translate/core';
import {ApiService, Project} from '../../../../services/api';
@Component({
  selector: 'app-proyects',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './proyects.component.html',
  styleUrls: ['./proyects.component.css']
})
export class ProyectsComponent implements OnInit {
  showFullProjects = false;
  selectedImage: string | null = null;
  carouselImages: string[] = [];
  currentCarouselIndex = 0;
  projects: Project[] = [];

  constructor(
    private translate: TranslateService,
    private apiService: ApiService
  ) {}

  ngOnInit() {
    this.loadProjects();
  }

  loadProjects() {
    this.apiService.getProjects().subscribe({
      next: (data) => {
        this.projects = data;
      },
      error: (error) => {
        console.error('Error loading projects:', error);
      }
    });
  }

  toggleFullProjects() {
    this.showFullProjects = !this.showFullProjects;
  }

  changeLang(language: string) {
    this.translate.use(language);
  }

  // ✅ Comprobación de array para Angular
  isArray(img: string | string[]): img is string[] {
    return Array.isArray(img);
  }

  // Zoom para imagen individual
  openImage(img: string) {
    this.selectedImage = img;
  }

  closeImage() {
    this.selectedImage = null;
  }

  // Carrusel para múltiples imágenes
  openCarousel(images: string[]) {
    this.carouselImages = images;
    this.currentCarouselIndex = 0;
  }

  closeCarousel() {
    this.carouselImages = [];
    this.currentCarouselIndex = 0;
  }

  prevCarouselImage() {
    if (this.carouselImages.length === 0) return;
    this.currentCarouselIndex = (this.currentCarouselIndex - 1 + this.carouselImages.length) % this.carouselImages.length;
  }

  nextCarouselImage() {
    if (this.carouselImages.length === 0) return;
    this.currentCarouselIndex = (this.currentCarouselIndex + 1) % this.carouselImages.length;
  }
  // Devuelve la primera imagen si es array, o la imagen misma si es string
getFirstImage(img: string | string[]): string {
  return Array.isArray(img) ? img[0] : img;
}

// Determina si se hace zoom o carrusel
openProjectImage(img: string | string[]) {
  if (Array.isArray(img)) {
    this.openCarousel(img);
  } else {
    this.openImage(img);
  }
}

}
<div class="proyects-card">
  <h2>{{ 'PROYECTOS.TITLE' | translate }}</h2>

  <!-- Proyectos -->
  <div class="projects-container">
    <div class="proyect-item" 
         *ngFor="let project of (showFullProjects ? projects : projects.slice(0, 2))">

      <!-- Imagen (soporta array o string) -->
      <img [src]="getFirstImage(project.img)"
           [alt]="'PROYECTOS.LIST.' + project.key + '.TITLE' | translate"
           class="proyect-image"
           (click)="openProjectImage(project.img)">

      <!-- Contenido -->
      <h3>{{ 'PROYECTOS.LIST.' + project.key + '.TITLE' | translate }}</h3>
      <p>{{ 'PROYECTOS.LIST.' + project.key + '.DESC' | translate }}</p>
      <a [href]="project.link" target="_blank" class="proyect-link">
        {{ 'PROYECTOS.LIST.' + project.key + '.LINK' | translate }}
      </a>

      <div class="tech-container">
        <h4>{{ 'PROYECTOS.TECNOLOGIAS' | translate }}</h4>
        <div class="tech-icons">
          <img *ngFor="let tech of project.techs" [src]="tech" alt="Technology icon" class="tech-icon">
        </div>
      </div>

    </div>
  </div>

  <!-- Botón ver más -->
  <div class="btn-ver-mas-container">
    <button (click)="toggleFullProjects()" class="btn-ver-mas">
      {{ showFullProjects ? ('PROYECTOS.VER_MENOS' | translate) : ('PROYECTOS.VER_MAS' | translate) }}
    </button>
  </div>

  <!-- Modal zoom -->
  <div class="modal" *ngIf="selectedImage" (click)="closeImage()">
    <img [src]="selectedImage" class="modal-image">
  </div>

  <!-- Modal carrusel -->
  <div class="modal-carousel" *ngIf="carouselImages.length" (click)="closeCarousel()">
    <button class="prev-btn" (click)="prevCarouselImage(); $event.stopPropagation()">‹</button>

    <img [src]="carouselImages[currentCarouselIndex]" class="carousel-image">

    <button class="next-btn" (click)="nextCarouselImage(); $event.stopPropagation()">›</button>

    <div class="carousel-indicator">
      {{ currentCarouselIndex + 1 }} / {{ carouselImages.length }}
    </div>
  </div>
</div>
